import{_ as t,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"路由懒加载","description":"当打包构建应用时，JavaScript 包会变得非常大，影响页面加载。如果我们能把不同路由对应的组件分割成不同的代码块，然后当路由被访问的时候才加载对应组件，这样就会更加高效。 Vue Router 支持开箱即用的动态导入，这意味着你可以用动态导入代替静态导入： // 将 //。","frontmatter":{"title":"路由懒加载","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"当打包构建应用时，JavaScript 包会变得非常大，影响页面加载。如果我们能把不同路由对应的组件分割成不同的代码块，然后当路由被访问的时候才加载对应组件，这样就会更加高效。 Vue Router 支持开箱即用的动态导入，这意味着你可以用动态导入代替静态导入： // 将 //。","sidebarWeight":59,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/路由懒加载.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/路由懒加载.md","filePath":"posts/Vue系统教程/04-路由与状态管理/路由懒加载.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/路由懒加载.md"};function u(i,e,n,p,c,l){return o(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="路由懒加载" tabindex="-1">路由懒加载 <a class="header-anchor" href="#路由懒加载" aria-label="Permalink to &quot;路由懒加载&quot;">​</a></h1><blockquote><p>本节目标：理解“路由懒加载”的核心思路，并能把它用于实际开发或面试表达。 当打包构建应用时，JavaScript 包会变得非常大，影响页面加载。如果我们能把不同路由对应的组件分割成不同的代码块，然后当路由被访问的时候才加载对应组件，这样就会更加高效。</p></blockquote><p>Vue Router 支持开箱即用的动态导入，这意味着你可以用动态导入代替静态导入： // 将 // import UserDetails from &#39;./views/UserDetails.vue&#39; // 替换成 const UserDetails = () =&gt; import(&#39;./views/UserDetails.vue&#39;) const router = createRouter({ // ... routes: [{ path: &#39;/users/:id&#39;, component: UserDetails }], }) component (和 components) 配置接收一个返回 Promise 组件的函数，Vue Router 只会在第一次进入页面时才会获取这个函数，然后使用缓存数据。这意味着你也可以使用更复杂的函数，只要它们返回一个 Promise ： const UserDetails = () =&gt; Promise.resolve({ /* 组件定义 */ }) 一般来说，对所有的路由都使用动态导入是个好主意。</p><p>注意 不要在路由中使用异步组件。异步组件仍然可以在路由组件中使用，但路由组件本身就是动态导入的。</p><p>如果你使用的是 webpack 之类的打包器，它将自动从代码分割中受益。 如果你使用的是 Babel，你将需要添加 syntax-dynamic-import 插件，才能使 Babel 正确地解析语法。</p><p>把组件按组分块 <strong>使用 webpack</strong> 有时候我们想把某个路由下的所有组件都打包在同个异步块 (chunk) 中。只需要使用命名 chunk，一个特殊的注释语法来提供 chunk name (需要 Webpack &gt; 2.4)： const UserDetails = () =&gt; import(/* webpackChunkName: &quot;group-user&quot; <em>/ &#39;./UserDetails.vue&#39;) const UserDashboard = () =&gt; import(/</em> webpackChunkName: &quot;group-user&quot; <em>/ &#39;./UserDashboard.vue&#39;) const UserProfileEdit = () =&gt; import(/</em> webpackChunkName: &quot;group-user&quot; */ &#39;./UserProfileEdit.vue&#39;) webpack 会将任何一个异步模块与相同的块名称组合到相同的异步块中。</p><p><strong>使用 Vite</strong> 在Vite中，你可以在rollupOptions下定义分块： // vite.config.js export default defineConfig({ build: { rollupOptions: { // <a href="https://rollupjs.org/guide/en/#outputmanualchunks" target="_blank" rel="noreferrer">https://rollupjs.org/guide/en/#outputmanualchunks</a> output: { manualChunks: { &#39;group-user&#39;: [ &#39;./src/UserDetails&#39;, &#39;./src/UserDashboard&#39;, &#39;./src/UserProfileEdit&#39;, ], }, }, }, }, })</p></div>',1)])])}const _=t(a,[["render",u]]);export{m as __pageData,_ as default};
